def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    if hasattr(sys, "set_int_max_str_digits"):
        sys.set_int_max_str_digits(0)

    size = sum(len(content) for content in cells.values()) + len(cells)
    required_limit = min(1_000_000_000, max(1000, 10 * size + 1000))
    if sys.getrecursionlimit() < required_limit:
        sys.setrecursionlimit(required_limit)

    token_pattern = re.compile(
        r"[A-Z][1-9][0-9]?|SUM|MIN|MAX|IF|[0-9]+|<>|<=|>=|[+\-*/(),:=<>]"
    )
    values = {}
    active = set()

    def parse(formula):
        tokens = token_pattern.findall(formula)
        pos = 0

        def expression():
            nonlocal pos
            node = term()
            while pos < len(tokens) and tokens[pos] in ("+", "-"):
                op = tokens[pos]
                pos += 1
                node = (op, node, term())
            return node

        def term():
            nonlocal pos
            node = unary()
            while pos < len(tokens) and tokens[pos] in ("*", "/"):
                op = tokens[pos]
                pos += 1
                node = (op, node, unary())
            return node

        def unary():
            nonlocal pos
            if tokens[pos] == "-":
                pos += 1
                return ("neg", unary())
            return atom()

        def atom():
            nonlocal pos
            token = tokens[pos]
            pos += 1

            if token[0].isdigit():
                return ("int", int(token))

            if token == "(":
                node = expression()
                pos += 1  # )
                return node

            if token == "IF":
                pos += 1  # (
                left = expression()
                op = tokens[pos]
                pos += 1
                right = expression()
                pos += 1  # ,
                then = expression()
                pos += 1  # ,
                otherwise = expression()
                pos += 1  # )
                return ("if", op, left, right, then, otherwise)

            if token in ("SUM", "MIN", "MAX"):
                pos += 1  # (
                args = []
                while True:
                    if (
                        pos + 1 < len(tokens)
                        and tokens[pos + 1] == ":"
                    ):
                        start = tokens[pos]
                        end = tokens[pos + 2]
                        pos += 3
                        args.append(("range", start, end))
                    else:
                        args.append(expression())
                    if tokens[pos] == ")":
                        pos += 1
                        break
                    pos += 1  # ,
                return ("function", token, args)

            return ("cell", token)

        return expression()

    def cell_value(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in active:
            return "#CYCLE!"

        active.add(name)
        content = cells[name]
        if content.startswith("="):
            value = evaluate(parse(content[1:]))
        else:
            value = int(content)
        active.remove(name)
        values[name] = value
        return value

    def evaluate(node):
        kind = node[0]

        if kind == "int":
            return node[1]
        if kind == "cell":
            return cell_value(node[1])
        if kind == "neg":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value

        if kind in ("+", "-", "*", "/"):
            left = evaluate(node[1])
            if isinstance(left, str):
                return left
            right = evaluate(node[2])
            if isinstance(right, str):
                return right

            if kind == "+":
                return left + right
            if kind == "-":
                return left - right
            if kind == "*":
                return left * right
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient

        if kind == "if":
            _, op, left_node, right_node, then_node, else_node = node
            left = evaluate(left_node)
            if isinstance(left, str):
                return left
            right = evaluate(right_node)
            if isinstance(right, str):
                return right

            if op == "=":
                condition = left == right
            elif op == "<>":
                condition = left != right
            elif op == "<":
                condition = left < right
            elif op == "<=":
                condition = left <= right
            elif op == ">":
                condition = left > right
            else:
                condition = left >= right
            return evaluate(then_node if condition else else_node)

        _, function, args = node
        result = None

        def combine(current, value):
            if current is None:
                return value
            if function == "SUM":
                return current + value
            if function == "MIN":
                return min(current, value)
            return max(current, value)

        for arg in args:
            if arg[0] == "range":
                start, end = arg[1], arg[2]
                first_row, last_row = sorted((int(start[1:]), int(end[1:])))
                first_col, last_col = sorted((ord(start[0]), ord(end[0])))
                for row in range(first_row, last_row + 1):
                    for col in range(first_col, last_col + 1):
                        name = chr(col) + str(row)
                        if name in cells:
                            value = cell_value(name)
                            if isinstance(value, str):
                                return value
                            result = combine(result, value)
            else:
                value = evaluate(arg)
                if isinstance(value, str):
                    return value
                result = combine(result, value)

        return 0 if result is None else result

    return {name: cell_value(name) for name in cells}
